import { ApplicationConfig, inject, provideAppInitializer, provideBrowserGlobalErrorListeners } from '@angular/core';
import {
    provideRouter,
    withPreloading,
    withInMemoryScrolling,
    withRouterConfig,
    withViewTransitions,
    withComponentInputBinding,
    NoPreloading  // ✅ changed from PreloadAllModules
} from '@angular/router';
import { provideHttpClient, withFetch, withInterceptors } from '@angular/common/http';
import { provideClientHydration, withEventReplay } from '@angular/platform-browser';
import {
    LUCIDE_ICONS, LucideIconProvider,
    ChevronRight, ChevronLeft, ChevronDown, Minus, Plus, Check, Play, X,Sparkles,  Globe,
    LayoutDashboard,Search,
    Compass, Target, PenTool, Code, Rocket,
    ShoppingBag, Store, Package, TrendingUp
} from 'lucide-angular';
import { importProvidersFrom } from '@angular/core';
import { TranslateModule } from '@ngx-translate/core';
import { routes } from './app.routes';
import { Title, Meta } from '@angular/platform-browser';
import { provideTranslateHttpLoader } from '@ngx-translate/http-loader';
import { HttpRequest, HttpHandlerFn } from '@angular/common/http';
import { TranslationService } from './core/services/translation.service';

// ✅ Fixed interceptor — only adds Content-Type on POST/PUT/PATCH
const contentTypeInterceptor = (req: HttpRequest<unknown>, next: HttpHandlerFn) => {
    if (['POST', 'PUT', 'PATCH'].includes(req.method)) {
        const modified = req.clone({
            setHeaders: { 'Content-Type': 'application/json' }
        });
        return next(modified);
    }
    return next(req); // ✅ GET requests untouched — SSR works correctly
};

export const appConfig: ApplicationConfig = {
    providers: [

        // ✅ HTTP — fixed interceptor
        provideHttpClient(
            withFetch(),
            withInterceptors([contentTypeInterceptor])
        ),

        // ✅ Translation
        importProvidersFrom(
            TranslateModule.forRoot({ fallbackLang: 'en' })
        ),
        provideTranslateHttpLoader({
            prefix: './assets/i18n/',
            suffix: '.json'
        }),
        provideAppInitializer(() => {
            inject(TranslationService);
        }),

        // ✅ Error handling
        provideBrowserGlobalErrorListeners(),

        // ✅ Router — fixed preloading strategy
        provideRouter(
            routes,
            withPreloading(NoPreloading), // ✅ don't preload all — kills TBT score
            withInMemoryScrolling({
                scrollPositionRestoration: 'enabled',
                anchorScrolling: 'enabled',
            }),
            withViewTransitions(),
            withComponentInputBinding(),
            withRouterConfig({
                onSameUrlNavigation: 'ignore', // ✅ changed from reload — conflicts hydration
                paramsInheritanceStrategy: 'always'
            })
        ),

        // ✅ Hydration
        provideClientHydration(withEventReplay()),

        // ✅ Icons
        {
            provide: LUCIDE_ICONS,
            multi: true,
            useValue: new LucideIconProvider({
                ChevronRight, ChevronLeft, ChevronDown, Minus, Plus, Check, Play, X,Sparkles,  Globe,
    LayoutDashboard,Search,
    Compass, Target, PenTool, Code, Rocket,
    ShoppingBag, Store, Package, TrendingUp
            }),
        },
        Title,
        Meta,
    ],
};
