import { DOCUMENT } from '@angular/common';
import { Inject, Injectable } from '@angular/core';
import { Meta, Title } from '@angular/platform-browser';
import { environment } from '../../../environments/environment';

export interface SeoMetadata {
	title?: string;
	description?: string;
	keywords?: string;
	canonicalPath?: string;
	ogTitle?: string;
	ogDescription?: string;
	ogUrl?: string;
	ogImage?: string;
	robots?: string;
}

@Injectable({
	providedIn: 'root'
})
export class SeoService {
	private readonly defaultImage = `${environment.url}/favicon/pixtar1200x630.png`;

	constructor(
		private readonly title: Title,
		private readonly meta: Meta,
		@Inject(DOCUMENT) private readonly document: Document
	) { }

	apply(metadata: SeoMetadata): void {
		const canonicalUrl = this.getAbsoluteUrl(metadata.canonicalPath ?? '/');
		const pageTitle = metadata.title ?? 'Pixtar UAE | Premium Branding & Web Design Dubai';
		const description = metadata.description
			?? 'Premium branding and website design in Dubai-UAE for industry leaders seeking exceptional designs as premium as their brand.';
		const keywords = metadata.keywords ?? '';
		const ogTitle = metadata.ogTitle ?? pageTitle;
		const ogDescription = metadata.ogDescription ?? description;
		const ogUrl = metadata.ogUrl ?? canonicalUrl;
		const ogImage = metadata.ogImage ?? this.defaultImage;

		this.title.setTitle(pageTitle);
		this.meta.updateTag({ name: 'description', content: description });
		this.meta.updateTag({ name: 'keywords', content: keywords });
		this.meta.updateTag({ property: 'og:title', content: ogTitle });
		this.meta.updateTag({ property: 'og:description', content: ogDescription });
		this.meta.updateTag({ property: 'og:url', content: ogUrl });
		this.meta.updateTag({ property: 'og:image', content: ogImage });

		if (metadata.robots) {
			this.meta.updateTag({ name: 'robots', content: metadata.robots });
		} else {
			this.meta.removeTag("name='robots'");
		}

		this.setCanonical(canonicalUrl);
	}

	addStructuredData(id: string, schema: Record<string, unknown>): void {
		const existingScript = this.document.getElementById(id);
		if (existingScript) {
			existingScript.textContent = JSON.stringify(schema);
			return;
		}

		const script = this.document.createElement('script');
		script.id = id;
		script.type = 'application/ld+json';
		script.textContent = JSON.stringify(schema);
		this.document.head.appendChild(script);
	}

	private setCanonical(url: string): void {
		let canonical = this.document.querySelector<HTMLLinkElement>('link[rel="canonical"]');

		if (!canonical) {
			canonical = this.document.createElement('link');
			canonical.setAttribute('rel', 'canonical');
			this.document.head.appendChild(canonical);
		}

		canonical.setAttribute('href', url);
	}

	private getAbsoluteUrl(path: string): string {
		if (!path) {
			return environment.url;
		}

		if (/^https?:\/\//i.test(path)) {
			return path;
		}

		const normalizedBase = environment.url.replace(/\/+$/, '');
		const normalizedPath = path.startsWith('/') ? path : `/${path}`;
		return `${normalizedBase}${normalizedPath}`;
	}
}
